window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5bbadb201e612bbc"]={"versions": [{"id": "FIG-5bbadb201e612bbc", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Security Extract Template (IdsDesign / Intrusion Detection System). Das Diagramm stellt die Metaklassen-Hierarchie für <code>SecurityEventContextMapping</code> sowie die Einbettung in das übergeordnete Element- und Mapping-Modell dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>IdsDesign</code> (Stereotyp «ARElement»): Repräsentiert das übergeordnete Entwurfselement. Es aggregiert bzw. referenziert über die Assoziationsrolle <code>+element</code> mit Kardinalität <code>0..*</code> und den Stereotypen «atpVariation,atpSplitable» Elemente des Typs <code>IdsCommonElement</code>.\n</li><li><code>IdsCommonElement</code> (Stereotyp «ARElement», kursiv dargestellt als abstrakt): Abstrakte Basisklasse für gemeinsame IDS-Elemente.\n</li><li><code>IdsMapping</code> (kursiv dargestellt als abstrakt): Spezialisiert <code>IdsCommonElement</code> via Generalisierung.\n</li><li><code>SecurityEventContextMapping</code> (kursiv dargestellt als abstrakt): Spezialisiert <code>IdsMapping</code> via Generalisierung und dient als Basis-Metaklasse für kontextbezogene Zuordnungen von Sicherheitsereignissen.\n</li><li><code>SecurityEventContextMappingBswModule</code>: Spezialisiert <code>SecurityEventContextMapping</code>. Enthält das Attribut <code>+ affectedBswModule: String [0..1]</code>.\n</li><li><code>SecurityEventContextMappingCommConnector</code>: Spezialisiert <code>SecurityEventContextMapping</code>. Besitzt keine eigenen Attribute im Diagramm.\n</li><li><code>SecurityEventContextMappingFunctionalCluster</code>: Spezialisiert <code>SecurityEventContextMapping</code>. Enthält das Attribut <code>+ affectedFunctionalCluster: String</code>.\n</li><li><code>SecurityEventContextMappingApplication</code>: Spezialisiert <code>SecurityEventContextMapping</code>. Enthält das Attribut <code>+ affectedApplication: String</code>.\n</li></ul>\n<p class=\"fig-p\">Zugehörige Notiz zu den «atpVariation»-Tags der Assoziation <code>element</code>:</p>\n<ul class=\"fig-list\"><li><code>atp.Status = draft</code>\n</li><li><code>vh.latestBindingTime = systemDesignTime</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm spezifiziert die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen. Sie definiert die statische Struktur zur Deklaration und Differenzierung von Sicherheitsereigniskontexten (BSW-Modul, Kommunikations-Connector, Functional Cluster oder Applikation) innerhalb eines AUTOSAR-Systems.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für AUTOSAR-Modellierungs- und Autorenumgebungen:</p>\n<ul class=\"fig-list\"><li>Spezialisierungen von <code>SecurityEventContextMapping</code> erlauben die präzise Adressierung des Kontexts betroffener Software-Einheiten sowohl in der Classic Platform (z. B. <code>affectedBswModule</code>) als auch in der Adaptive Platform (z. B. <code>affectedFunctionalCluster</code>).\n</li><li>Die Rolle <code>+element</code> an <code>IdsDesign</code> unterliegt der Variabilitätsbindung (<code>vh.latestBindingTime = systemDesignTime</code>) und ist splittbar («atpSplitable»). Der Reifegrad des Variationspunkts ist mit <code>draft</code> annotiert.\n</li></ul>"}, {"id": "FIG-46f5f9d8134c710c", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Metamodells im Kontext des Security Extract Template (IdsDesign / Intrusion Detection System). Das Diagramm stellt die Metaklassen-Hierarchie für <code>SecurityEventContextMapping</code> sowie die Einbettung in das übergeordnete Element- und Mapping-Modell dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>IdsDesign</code> (Stereotyp «ARElement»): Repräsentiert das übergeordnete Entwurfselement. Es referenziert über die Assoziationsrolle <code>+element</code> mit Kardinalität <code>0..*</code> und den Stereotypen «atpVariation,atpSplitable» Instanzen von <code>IdsCommonElement</code>.\n</li><li><code>IdsCommonElement</code> (Stereotyp «ARElement», kursiv dargestellt als abstrakt): Abstrakte Basisklasse für gemeinsame IDS-Elemente.\n</li><li><code>IdsMapping</code> (kursiv dargestellt als abstrakt): Spezialisiert <code>IdsCommonElement</code> via Generalisierung.\n</li><li><code>SecurityEventContextMapping</code> (kursiv dargestellt als abstrakt): Spezialisiert <code>IdsMapping</code> via Generalisierung und dient als Basis-Metaklasse für kontextbezogene Zuordnungen von Sicherheitsereignissen.\n</li><li><code>SecurityEventContextMappingBswModule</code>: Spezialisiert <code>SecurityEventContextMapping</code>. Enthält das Attribut <code>+ affectedBswModule: String [0..1]</code>.\n</li><li><code>SecurityEventContextMappingCommConnector</code>: Spezialisiert <code>SecurityEventContextMapping</code>. Besitzt keine eigenen Attribute im Diagramm.\n</li><li><code>SecurityEventContextMappingFunctionalCluster</code>: Spezialisiert <code>SecurityEventContextMapping</code>. Enthält das Attribut <code>+ affectedFunctionalCluster: String</code>.\n</li><li><code>SecurityEventContextMappingApplication</code>: Spezialisiert <code>SecurityEventContextMapping</code>. Enthält das Attribut <code>+ affectedApplication: String</code>.\n</li></ul>\n<p class=\"fig-p\">Zugehörige Notiz zu den «atpVariation»-Tags der Assoziation <code>element</code>:</p>\n<ul class=\"fig-list\"><li><code>atp.Status = candidate</code>\n</li><li><code>vh.latestBindingTime = systemDesignTime</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm spezifiziert die Abbildung keine dynamischen Interaktionen oder Laufzeitsequenzen. Sie definiert die statische Struktur zur Deklaration und Differenzierung von Sicherheitsereigniskontexten (BSW-Modul, Kommunikations-Connector, Functional Cluster oder Applikation) innerhalb eines AUTOSAR-Systems.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Definition für AUTOSAR-Modellierungs- und Autorenumgebungen:</p>\n<ul class=\"fig-list\"><li>Spezialisierungen von <code>SecurityEventContextMapping</code> erlauben die präzise Adressierung des Kontexts betroffener Software-Einheiten sowohl in der Classic Platform (z. B. <code>affectedBswModule</code>) als auch in der Adaptive Platform (z. B. <code>affectedFunctionalCluster</code>).\n</li><li>Die Rolle <code>+element</code> an <code>IdsDesign</code> unterliegt der Variabilitätsbindung (<code>vh.latestBindingTime = systemDesignTime</code>) und ist splittbar («atpSplitable»). Der Reifegrad des Variationspunkts ist mit dem Status <code>candidate</code> annotiert, was eine fortgeschrittene Standardisierungsreife vor der finalen Freigabe anzeigt.\n</li></ul>"}], "trans": [{"from": "FIG-5bbadb201e612bbc", "to": "FIG-46f5f9d8134c710c", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>In der Notiz zu den «atpVariation»-Tags der Assoziation <code>element</code> zwischen <code>IdsDesign</code> und <code>IdsCommonElement</code>: <code>atp.Status</code> von <code>draft</code> auf <code>candidate</code> geändert.\n</li><li>Layout der oberen Hierarchieebene von vertikaler Anordnung auf horizontale Anordnung umstrukturiert (<code>IdsMapping</code> erbt nach rechts von <code>IdsCommonElement</code>, <code>IdsDesign</code> aggregiert/referenziert <code>IdsCommonElement</code> horizontal nach links).\n</li></ul>"}]};
